mapper.select:
SELECT U.users_id, users_profile, users_name, users_nickname, users_login_type, users_email, department_name, YEAR(CURDATE()) - YEAR(users_birth) AS usersAge, users_gender, users_status, users_rejected_reason FROM users U JOIN department D ON U.department_id = D.department_id
users_name LIKE CONCAT('%', #{query}, '%')
ORDER BY U.users_id LIMIT #{offset}, #{pageSize}

SELECT YEAR (users_created_at) AS createdAt, COUNT (*) userCount
FROM users
GROUP BY YEAR (users_created_at);

SELECT MONTH (users_created_at) AS createdAt, COUNT (*) userCount
FROM users
GROUP BY MONTH (users_created_at);

SELECT DAY (users_created_at) AS createdAt, COUNT (*) userCount
FROM users
GROUP BY DAY (users_created_at);

SELECT O.owner_id AS ownerId, store_mainimage, store_name, owner_email, category_name, store_avgstar, owner_tel, store_tel, store_address, store_intro, store_status, store_reject_reason FROM owner O JOIN store S ON O.owner_id = S.owner_id JOIN category C ON S.category_id = C.category_id
store_name LIKE CONCAT('%', #{query}, '%')
ORDER BY O.owner_id LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE store

    store_status = #{storeStatus}

        , store_reject_reason = #{storeRejectReason}


WHERE owner_id = #{ownerId}

UPDATE users

    users_status = #{usersStatus}

        , users_rejected_reason = #{usersRejectReason}


WHERE users_id = #{usersId}

mapper.select:
SELECT B.board_id, U.users_id, U.users_nickname, B.board_title, B.board_status, B.board_date, B.board_viewcount FROM board B JOIN users U ON B.users_id = U.users_id
U.users_nickname LIKE CONCAT('%', #{query}, '%')
ORDER BY B.board_id LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE review
SET review_status = 'N'
WHERE review_id = #{reviewId}

